#include <iostream>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

Node* findLCA(Node* root, Node* p, Node* q) {
    // Base Case: empty tree or if we found p or q
    if (root == nullptr || root == p || root == q) {
        return root;
    }

    // Recurse left and right
    Node* leftLCA = findLCA(root->left, p, q);
    Node* rightLCA = findLCA(root->right, p, q);

    // If both left and right calls returned non-null, current node is the LCA!
    if (leftLCA != nullptr && rightLCA != nullptr) {
        return root;
    }

    // Otherwise, return the non-null result
    return (leftLCA != nullptr) ? leftLCA : rightLCA;
}
